package edu.synergy.algorithms.quicksort;
import java.util.concurrent.ThreadLocalRandom;
public final class TeamQuickSort { private TeamQuickSort(){} public static FootballTeam[] randomTeams(){FootballTeam[]teams=new FootballTeam[10];for(int i=0;i<teams.length;i++)teams[i]=new FootballTeam("Team "+(i+1),ThreadLocalRandom.current().nextInt(0,101));return teams;} public static void sort(FootballTeam[]a){quick(a,0,a.length-1);} private static void quick(FootballTeam[]a,int lo,int hi){if(lo>=hi)return;int p=partition(a,lo,hi);quick(a,lo,p-1);quick(a,p+1,hi);} private static int partition(FootballTeam[]a,int lo,int hi){int pivot=a[hi].goalCountBySeason(),i=lo;for(int j=lo;j<hi;j++)if(a[j].goalCountBySeason()<=pivot){var t=a[i];a[i++]=a[j];a[j]=t;}var t=a[i];a[i]=a[hi];a[hi]=t;return i;} }
